import heapq


def dependency_solver(preference, name_order):
    def solve(data):
        packages = data["packages"]
        names = sorted(packages)
        features = set(data.get("features", []))
        roots = data["roots"]
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        choices = []
        for name in names:
            versions = sorted(row["version"] for row in packages[name]
                              if row["version"] not in blocked.get(name, [])
                              and (name not in pins or row["version"] == pins[name]))
            choices.append([-1] + versions)

        best_vector = None
        best = None
        for values in product(*choices):
            selected = dict(zip(names, values))
            if any(selected.get(name, -1) < bounds[0] or
                   selected.get(name, -1) > bounds[1]
                   for name, bounds in roots.items()):
                continue
            # A pin constrains an installed package, but cannot install one.
            rows = {}
            for name, version in selected.items():
                if version == -1:
                    continue
                rows[name] = next(row for row in packages[name]
                                  if row["version"] == version)

            edges = {name: [] for name in rows}
            valid = True
            for name, row in rows.items():
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    other = dep["name"]
                    version = selected.get(other, -1)
                    if version < dep["min"] or version > dep["max"]:
                        valid = False
                        break
                    edges[name].append(other)
                if not valid:
                    break
            if not valid:
                continue

            reachable = set()
            stack = [name for name in roots]
            while stack:
                name = stack.pop()
                if name in reachable:
                    continue
                reachable.add(name)
                stack.extend(edges.get(name, []))
            if reachable != set(rows):
                continue

            done, active = set(), set()
            def visit(name):
                if name in active:
                    return False
                if name in done:
                    return True
                active.add(name)
                for other in edges.get(name, []):
                    if not visit(other):
                        return False
                active.remove(name)
                done.add(name)
                return True
            if not all(visit(name) for name in rows):
                continue

            ordered = sorted(names, reverse=(name_order == "descending"))
            vector = tuple(selected[name] for name in ordered)
            if best_vector is None or (vector > best_vector if preference == "maximum"
                                       else vector < best_vector):
                best_vector = vector
                best = {name: selected[name] for name in names
                        if selected[name] != -1}

        return {"versions": best} if best is not None else {"error": "unsatisfiable"}
    return solve


def _round(numerator, denominator, mode):
    if mode == "half_up":
        return (numerator + denominator // 2) // denominator
    return numerator // denominator


def ledger(data):
    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for pos, event in enumerate(data["events"]):
        if event.get("sequence", 0) > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(pos))
        key = (event.get("revision", 0), pos)
        if event_id not in winners or key > winners[event_id][0]:
            winners[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]
    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = _round(raw * (10000 - discount), 10000, mode)
        tax = _round(raw * event.get("tax_bp", 0), 10000, mode)
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def quota_intervals(data):
    jobs = data["jobs"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    k = data["k"]
    available = [job for job in jobs if job["id"] not in blocked]
    best_value = None
    best_ids = None

    for subset in combinations(available, k):
        ids = sorted(job["id"] for job in subset)
        idset = set(ids)
        if not mandatory.issubset(idset):
            continue
        counts = {}
        for job in subset:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not (low <= counts.get(group, 0) <= high)
               for group, (low, high) in quotas.items()):
            continue

        active = []
        valid = True
        for job in sorted(subset, key=lambda j: (j["start"], j["end"], j["id"])):
            while active and active[0] <= job["start"]:
                heapq.heappop(active)
            if len(active) >= 2:
                valid = False
                break
            heapq.heappush(active, job["end"])
        if not valid:
            continue

        value = sum(job["value"] for job in subset)
        if (best_value is None or value > best_value or
                (value == best_value and ids > best_ids)):
            best_value, best_ids = value, ids

    if best_value is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


def temporal_routes(data):
    required = data.get("required", [])
    bit = {node: 0 for node in required}
    for i, node in enumerate(required):
        bit[node] = bit.get(node, 0) | (1 << i)
    full = (1 << len(required)) - 1
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    source = data["source"]
    start_mask = bit.get(source, 0)
    start_state = (source, start_mask, data["coupons"])
    distances = {start_state: data["start"]}
    queue = [(data["start"], source, start_mask, data["coupons"])]

    while queue:
        time, node, mask, remaining = heapq.heappop(queue)
        state = (node, mask, remaining)
        if time != distances.get(state):
            continue
        if node == data["target"] and mask == full:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], remaining)]
            if remaining:
                options.append((max(1, edge["duration"] - edge.get("discount", 0)), remaining - 1))
            for duration, next_remaining in options:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                nxt = edge["v"]
                next_mask = mask | bit.get(nxt, 0)
                next_state = (nxt, next_mask, next_remaining)
                if arrival < distances.get(next_state, float("inf")):
                    distances[next_state] = arrival
                    heapq.heappush(queue, (arrival, nxt, next_mask, next_remaining))
    return {"arrival": None}


